#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""7-temel-dini-bilgiler-14 özel vektörel görselleri (6 bölüm, zengin SVG)."""

GORSELLER = {'b1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MÜKELLEF VE EF\'ÂL-İ MÜKELLEFÎN (SORUMLULUK HÜKÜMLERİ)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Mükellef Olmanın İki Temel Şartı</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• 1. Akıllı Olmak: İyiyi kötüden ayırt edebilecek</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  akıl sağlığına sahip olmak (Dinen temel şarttır).</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• 2. Ergenlik (Buluğ) Çağına Ulaşmış Olmak:</text>\n  <text x="40" y="160" font-size="11" fill="#334155">  Çocukluk dönemini tamamlayıp yetişkinliğe girmek.</text>\n  <text x="40" y="186" font-size="11" font-weight="bold" fill="#1e40af">• Tanım: Dinin emir ve yasaklarından sorumlu olan</text>\n  <text x="40" y="204" font-size="11" font-weight="bold" fill="#1e40af">  akıllı ve ergen Müslümana MÜKELLEF denir.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Ef\'âl-i Mükellefîn (8 Hüküm Basamağı)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Yapılması İstenenler: 1) Farz, 2) Vacip,</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  3) Sünnet (ve Müstehap / Nafile).</text>\n  <text x="375" y="142" font-size="11" fill="#334155">• Serbest Olanlar: 4) Mübah (Yemek, içmek, uyumak).</text>\n  <text x="375" y="168" font-size="11" fill="#334155">• Kaçınılması İstenenler: 5) Mekruh (Hoş görülmeyen),</text>\n  <text x="375" y="186" font-size="11" fill="#334155">  6) Haram (Kesin yasaklanan), 7) Müfsit (İbadeti bozan).</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Hükümlerine Göre İbadetler: Farz, Vacip, Sünnet</text>\n</svg>', '1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MÜKELLEF VE EF\'ÂL-İ MÜKELLEFÎN (SORUMLULUK HÜKÜMLERİ)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Mükellef Olmanın İki Temel Şartı</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• 1. Akıllı Olmak: İyiyi kötüden ayırt edebilecek</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  akıl sağlığına sahip olmak (Dinen temel şarttır).</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• 2. Ergenlik (Buluğ) Çağına Ulaşmış Olmak:</text>\n  <text x="40" y="160" font-size="11" fill="#334155">  Çocukluk dönemini tamamlayıp yetişkinliğe girmek.</text>\n  <text x="40" y="186" font-size="11" font-weight="bold" fill="#1e40af">• Tanım: Dinin emir ve yasaklarından sorumlu olan</text>\n  <text x="40" y="204" font-size="11" font-weight="bold" fill="#1e40af">  akıllı ve ergen Müslümana MÜKELLEF denir.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Ef\'âl-i Mükellefîn (8 Hüküm Basamağı)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Yapılması İstenenler: 1) Farz, 2) Vacip,</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  3) Sünnet (ve Müstehap / Nafile).</text>\n  <text x="375" y="142" font-size="11" fill="#334155">• Serbest Olanlar: 4) Mübah (Yemek, içmek, uyumak).</text>\n  <text x="375" y="168" font-size="11" fill="#334155">• Kaçınılması İstenenler: 5) Mekruh (Hoş görülmeyen),</text>\n  <text x="375" y="186" font-size="11" fill="#334155">  6) Haram (Kesin yasaklanan), 7) Müfsit (İbadeti bozan).</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Hükümlerine Göre İbadetler: Farz, Vacip, Sünnet</text>\n</svg>', 'b2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FARZ İBADETLER: FARZ-I AYIN VE FARZ-I KİFAYE</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Farz-ı Ayın (Bireysel Zorunluluk)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Her mükellefin bizzat kendisinin yapmakla</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  yükümlü olduğu, başkası yapınca sorumluluğu</text>\n  <text x="40" y="134" font-size="11" fill="#334155">  düşmeyen kesin farzlardır.</text>\n  <text x="40" y="160" font-size="11" font-weight="bold" fill="#1e40af">• Örnekler:</text>\n  <text x="40" y="180" font-size="11" fill="#334155">  - Günde 5 vakit namaz ve Cuma namazı</text>\n  <text x="40" y="198" font-size="11" fill="#334155">  - Ramazan orucu, Zekât vermek ve Hac</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">2. Farz-ı Kifaye (Toplumsal Sorumluluk)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Müslümanlardan bir kısmının yapmasıyla diğerlerinin</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  üzerinden sorumluluğun kalktığı; ancak hiç kimse</text>\n  <text x="375" y="134" font-size="11" fill="#334155">  yapmazsa tüm toplumun sorumlu olduğu farzdır.</text>\n  <text x="375" y="160" font-size="11" font-weight="bold" fill="#92400e">• Örnekler:</text>\n  <text x="375" y="180" font-size="11" fill="#334155">  - Cenaze namazı kılmak ve cenazeyi defnetmek</text>\n  <text x="375" y="198" font-size="11" fill="#334155">  - Verilen selama karşılık vermek, toplum için uzmanlık</text>\n</svg>', '2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FARZ İBADETLER: FARZ-I AYIN VE FARZ-I KİFAYE</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Farz-ı Ayın (Bireysel Zorunluluk)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Her mükellefin bizzat kendisinin yapmakla</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  yükümlü olduğu, başkası yapınca sorumluluğu</text>\n  <text x="40" y="134" font-size="11" fill="#334155">  düşmeyen kesin farzlardır.</text>\n  <text x="40" y="160" font-size="11" font-weight="bold" fill="#1e40af">• Örnekler:</text>\n  <text x="40" y="180" font-size="11" fill="#334155">  - Günde 5 vakit namaz ve Cuma namazı</text>\n  <text x="40" y="198" font-size="11" fill="#334155">  - Ramazan orucu, Zekât vermek ve Hac</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">2. Farz-ı Kifaye (Toplumsal Sorumluluk)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Müslümanlardan bir kısmının yapmasıyla diğerlerinin</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  üzerinden sorumluluğun kalktığı; ancak hiç kimse</text>\n  <text x="375" y="134" font-size="11" fill="#334155">  yapmazsa tüm toplumun sorumlu olduğu farzdır.</text>\n  <text x="375" y="160" font-size="11" font-weight="bold" fill="#92400e">• Örnekler:</text>\n  <text x="375" y="180" font-size="11" fill="#334155">  - Cenaze namazı kılmak ve cenazeyi defnetmek</text>\n  <text x="375" y="198" font-size="11" fill="#334155">  - Verilen selama karşılık vermek, toplum için uzmanlık</text>\n</svg>', 'b3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">VACİP İBADETLER: TANIMI, HÜKMÜ VE ÖRNEKLERİ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Vacip Hükmünün Özellikleri</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Yapılması farz kadar kesin olmamakla birlikte</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  güçlü bir delille (zannî delille) emredilen ibadettir.</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• Uygulama (amel) bakımından farz gibidir; yapan</text>\n  <text x="40" y="160" font-size="11" fill="#334155">  büyük sevap kazanır, mazeretsiz terk eden</text>\n  <text x="40" y="178" font-size="11" fill="#334155">  günahkâr olur.</text>\n  <text x="40" y="204" font-size="11" font-weight="bold" fill="#9d174d">• Namazda vacip unutulursa Sehiv Secdesi yapılır.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Başlıca Vacip İbadet Örnekleri</text>\n  <text x="375" y="98" font-size="11.5" fill="#334155">• 1. Ramazan ve Kurban Bayramı namazlarını kılmak</text>\n  <text x="375" y="122" font-size="11.5" fill="#334155">• 2. Yatsıdan sonra Vitir namazını kılmak</text>\n  <text x="375" y="146" font-size="11.5" fill="#334155">• 3. Kurban Bayramı\'nda Udhiyye kurbanı kesmek</text>\n  <text x="375" y="170" font-size="11.5" fill="#334155">• 4. Ramazan\'da Fıtır sadakası (Fitre) vermek</text>\n  <text x="375" y="194" font-size="11.5" fill="#334155">• 5. Adak (nezir) ibadetini yerine getirmek</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">6. Namazda Fatiha okumak, Hacda Sa\'y ve Müzdelife</text>\n</svg>', '3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">VACİP İBADETLER: TANIMI, HÜKMÜ VE ÖRNEKLERİ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Vacip Hükmünün Özellikleri</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Yapılması farz kadar kesin olmamakla birlikte</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  güçlü bir delille (zannî delille) emredilen ibadettir.</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• Uygulama (amel) bakımından farz gibidir; yapan</text>\n  <text x="40" y="160" font-size="11" fill="#334155">  büyük sevap kazanır, mazeretsiz terk eden</text>\n  <text x="40" y="178" font-size="11" fill="#334155">  günahkâr olur.</text>\n  <text x="40" y="204" font-size="11" font-weight="bold" fill="#9d174d">• Namazda vacip unutulursa Sehiv Secdesi yapılır.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Başlıca Vacip İbadet Örnekleri</text>\n  <text x="375" y="98" font-size="11.5" fill="#334155">• 1. Ramazan ve Kurban Bayramı namazlarını kılmak</text>\n  <text x="375" y="122" font-size="11.5" fill="#334155">• 2. Yatsıdan sonra Vitir namazını kılmak</text>\n  <text x="375" y="146" font-size="11.5" fill="#334155">• 3. Kurban Bayramı\'nda Udhiyye kurbanı kesmek</text>\n  <text x="375" y="170" font-size="11.5" fill="#334155">• 4. Ramazan\'da Fıtır sadakası (Fitre) vermek</text>\n  <text x="375" y="194" font-size="11.5" fill="#334155">• 5. Adak (nezir) ibadetini yerine getirmek</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">6. Namazda Fatiha okumak, Hacda Sa\'y ve Müzdelife</text>\n</svg>', 'b4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÜNNET İBADETLER: MÜEKKEDE VE GAYRİ MÜEKKEDE</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Sünnet-i Müekkede (Kuvvetli Sünnet)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Hz. Peygamber\'in (s.a.v.) devamlı yaptığı ve</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  çok nadir terk ettiği sünnetlerdir.</text>\n  <text x="40" y="142" font-size="11" font-weight="bold" fill="#1e40af">• Örnekler:</text>\n  <text x="40" y="162" font-size="11" fill="#334155">  - Sabah, öğle ve akşam namazlarının sünnetleri</text>\n  <text x="40" y="180" font-size="11" fill="#334155">  - Ramazan ayında Teravih namazı kılmak</text>\n  <text x="40" y="198" font-size="11" fill="#334155">  - Namazları cemaatle kılmak, ezan ve kamet</text>\n  <text x="40" y="216" font-size="11" fill="#334155">  - Misvak/diş fırçası kullanmak, Umre yapmak</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">2. Sünnet-i Gayri Müekkede (Müstehap)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Hz. Peygamber\'in bazen sevap için yaptığı,</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  bazen de ümmetine zorluk olmasın diye</text>\n  <text x="375" y="134" font-size="11" fill="#334155">  terk ettiği sünnetlerdir (Mendup / Müstehap).</text>\n  <text x="375" y="160" font-size="11" font-weight="bold" fill="#92400e">• Örnekler:</text>\n  <text x="375" y="180" font-size="11" fill="#334155">  - İkindi namazının 4 rekâtlık ilk sünneti</text>\n  <text x="375" y="198" font-size="11" fill="#334155">  - Yatsı namazının 4 rekâtlık ilk sünneti</text>\n  <text x="375" y="216" font-size="11" fill="#334155">  - Pazartesi-Perşembe oruçları, sadaka vermek</text>\n</svg>', '4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÜNNET İBADETLER: MÜEKKEDE VE GAYRİ MÜEKKEDE</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Sünnet-i Müekkede (Kuvvetli Sünnet)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Hz. Peygamber\'in (s.a.v.) devamlı yaptığı ve</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  çok nadir terk ettiği sünnetlerdir.</text>\n  <text x="40" y="142" font-size="11" font-weight="bold" fill="#1e40af">• Örnekler:</text>\n  <text x="40" y="162" font-size="11" fill="#334155">  - Sabah, öğle ve akşam namazlarının sünnetleri</text>\n  <text x="40" y="180" font-size="11" fill="#334155">  - Ramazan ayında Teravih namazı kılmak</text>\n  <text x="40" y="198" font-size="11" fill="#334155">  - Namazları cemaatle kılmak, ezan ve kamet</text>\n  <text x="40" y="216" font-size="11" fill="#334155">  - Misvak/diş fırçası kullanmak, Umre yapmak</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">2. Sünnet-i Gayri Müekkede (Müstehap)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Hz. Peygamber\'in bazen sevap için yaptığı,</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  bazen de ümmetine zorluk olmasın diye</text>\n  <text x="375" y="134" font-size="11" fill="#334155">  terk ettiği sünnetlerdir (Mendup / Müstehap).</text>\n  <text x="375" y="160" font-size="11" font-weight="bold" fill="#92400e">• Örnekler:</text>\n  <text x="375" y="180" font-size="11" fill="#334155">  - İkindi namazının 4 rekâtlık ilk sünneti</text>\n  <text x="375" y="198" font-size="11" fill="#334155">  - Yatsı namazının 4 rekâtlık ilk sünneti</text>\n  <text x="375" y="216" font-size="11" fill="#334155">  - Pazartesi-Perşembe oruçları, sadaka vermek</text>\n</svg>', 'b5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FARZ, VACİP VE SÜNNET İBADETLERİN MUKAYESESİ (TDB.1.2.3)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Ortak Yönleri (Benzerlik)</text>\n  <text x="35" y="98" font-size="11" fill="#334155">• Üçü de Yüce Allah\'ın rızasını</text>\n  <text x="35" y="116" font-size="11" fill="#334155">  kazanmak için yapılır (İhlas).</text>\n  <text x="35" y="140" font-size="11" fill="#334155">• Üçünü de yerine getiren mümin</text>\n  <text x="35" y="158" font-size="11" fill="#334155">  sevap kazanır ve Allah\'a</text>\n  <text x="35" y="176" font-size="11" fill="#334155">  yakınlaşır.</text>\n  <text x="35" y="200" font-size="11" fill="#1e40af">• Üçü de ahlakı güzelleştirir.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">Terk Edilme ve Kaza Farkı</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Farz ve Vacip: Mazeretsiz terk</text>\n  <text x="260" y="116" font-size="11" fill="#334155">  edilmesi günahtır; kazası</text>\n  <text x="260" y="134" font-size="11" fill="#334155">  gerekir.</text>\n  <text x="260" y="160" font-size="11" fill="#334155">• Sünnet: Terk edilmesi günah</text>\n  <text x="260" y="178" font-size="11" fill="#334155">  değildir, ancak Peygamber</text>\n  <text x="260" y="196" font-size="11" fill="#334155">  şefaatinden ve sevaptan mahrumiyet.</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">İnkâr Edilme Hükmü Farkı</text>\n  <text x="485" y="98" font-size="11" fill="#334155">• Farz: Kesin delille (ayetle)</text>\n  <text x="485" y="116" font-size="11" fill="#334155">  sabit olduğu için inkâr eden</text>\n  <text x="485" y="134" font-size="11" font-weight="bold" fill="#166534">  dinden çıkar.</text>\n  <text x="485" y="160" font-size="11" fill="#334155">• Vacip: Delili zannî olduğu</text>\n  <text x="485" y="178" font-size="11" fill="#334155">  için inkâr eden dinden çıkmaz</text>\n  <text x="485" y="196" font-size="11" fill="#334155">  fakat büyük günahkâr olur.</text>\n</svg>', '5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FARZ, VACİP VE SÜNNET İBADETLERİN MUKAYESESİ (TDB.1.2.3)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Ortak Yönleri (Benzerlik)</text>\n  <text x="35" y="98" font-size="11" fill="#334155">• Üçü de Yüce Allah\'ın rızasını</text>\n  <text x="35" y="116" font-size="11" fill="#334155">  kazanmak için yapılır (İhlas).</text>\n  <text x="35" y="140" font-size="11" fill="#334155">• Üçünü de yerine getiren mümin</text>\n  <text x="35" y="158" font-size="11" fill="#334155">  sevap kazanır ve Allah\'a</text>\n  <text x="35" y="176" font-size="11" fill="#334155">  yakınlaşır.</text>\n  <text x="35" y="200" font-size="11" fill="#1e40af">• Üçü de ahlakı güzelleştirir.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">Terk Edilme ve Kaza Farkı</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Farz ve Vacip: Mazeretsiz terk</text>\n  <text x="260" y="116" font-size="11" fill="#334155">  edilmesi günahtır; kazası</text>\n  <text x="260" y="134" font-size="11" fill="#334155">  gerekir.</text>\n  <text x="260" y="160" font-size="11" fill="#334155">• Sünnet: Terk edilmesi günah</text>\n  <text x="260" y="178" font-size="11" fill="#334155">  değildir, ancak Peygamber</text>\n  <text x="260" y="196" font-size="11" fill="#334155">  şefaatinden ve sevaptan mahrumiyet.</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">İnkâr Edilme Hükmü Farkı</text>\n  <text x="485" y="98" font-size="11" fill="#334155">• Farz: Kesin delille (ayetle)</text>\n  <text x="485" y="116" font-size="11" fill="#334155">  sabit olduğu için inkâr eden</text>\n  <text x="485" y="134" font-size="11" font-weight="bold" fill="#166534">  dinden çıkar.</text>\n  <text x="485" y="160" font-size="11" fill="#334155">• Vacip: Delili zannî olduğu</text>\n  <text x="485" y="178" font-size="11" fill="#334155">  için inkâr eden dinden çıkmaz</text>\n  <text x="485" y="196" font-size="11" fill="#334155">  fakat büyük günahkâr olur.</text>\n</svg>', 'b6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İBADETİN RUHU: HAMD, İHLAS, SÜNNETE UYUM VE SALİH AMEL</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İbadetlerin Kabul Olmasının 3 Şartı</text>\n  <text x="40" y="98" font-size="11.5" fill="#334155">• 1. İman: İbadetin geçerli olması için öncelikle</text>\n  <text x="40" y="116" font-size="11.5" fill="#334155">  tevhit ve iman esaslarına inanmak şarttır.</text>\n  <text x="40" y="142" font-size="11.5" fill="#334155">• 2. İhlas (Samimiyet): Gösterişten (riyadan) uzak,</text>\n  <text x="40" y="160" font-size="11.5" fill="#334155">  yalnız Allah rızası için ibadet etmektir.</text>\n  <text x="40" y="186" font-size="11.5" fill="#334155">• 3. Sünnete Uygunluk: İbadetleri Hz. Peygamber\'in</text>\n  <text x="40" y="204" font-size="11.5" fill="#334155">  gösterdiği ve öğrettiği biçimde yapmaktır.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Hamd ve Salih Amel Kavramları</text>\n  <text x="375" y="98" font-size="11.5" fill="#334155">• Hamd: Nimetlerin gerçek sahibi olan Allah\'ı</text>\n  <text x="375" y="116" font-size="11.5" fill="#334155">  sevgi, saygı ve şükranla övmektir (Elhamdülillah).</text>\n  <text x="375" y="142" font-size="11.5" fill="#334155">• Salih Amel: İman ve ihlasla yapılan, insana</text>\n  <text x="375" y="160" font-size="11.5" fill="#334155">  ve topluma fayda sağlayan her türlü güzel</text>\n  <text x="375" y="178" font-size="11.5" fill="#334155">  davranış ve ibadettir.</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Sünnet ve Nafile İbadetler Farzların Koruyucu Kalkanıdır</text>\n</svg>', '6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İBADETİN RUHU: HAMD, İHLAS, SÜNNETE UYUM VE SALİH AMEL</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İbadetlerin Kabul Olmasının 3 Şartı</text>\n  <text x="40" y="98" font-size="11.5" fill="#334155">• 1. İman: İbadetin geçerli olması için öncelikle</text>\n  <text x="40" y="116" font-size="11.5" fill="#334155">  tevhit ve iman esaslarına inanmak şarttır.</text>\n  <text x="40" y="142" font-size="11.5" fill="#334155">• 2. İhlas (Samimiyet): Gösterişten (riyadan) uzak,</text>\n  <text x="40" y="160" font-size="11.5" fill="#334155">  yalnız Allah rızası için ibadet etmektir.</text>\n  <text x="40" y="186" font-size="11.5" fill="#334155">• 3. Sünnete Uygunluk: İbadetleri Hz. Peygamber\'in</text>\n  <text x="40" y="204" font-size="11.5" fill="#334155">  gösterdiği ve öğrettiği biçimde yapmaktır.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Hamd ve Salih Amel Kavramları</text>\n  <text x="375" y="98" font-size="11.5" fill="#334155">• Hamd: Nimetlerin gerçek sahibi olan Allah\'ı</text>\n  <text x="375" y="116" font-size="11.5" fill="#334155">  sevgi, saygı ve şükranla övmektir (Elhamdülillah).</text>\n  <text x="375" y="142" font-size="11.5" fill="#334155">• Salih Amel: İman ve ihlasla yapılan, insana</text>\n  <text x="375" y="160" font-size="11.5" fill="#334155">  ve topluma fayda sağlayan her türlü güzel</text>\n  <text x="375" y="178" font-size="11.5" fill="#334155">  davranış ve ibadettir.</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Sünnet ve Nafile İbadetler Farzların Koruyucu Kalkanıdır</text>\n</svg>'}

def uygula(v):
    for i, b in enumerate(v.get('bolumler', []), 1):
        if f'b{i}' in GORSELLER:
            b['gorsel'] = GORSELLER[f'b{i}']
